  ('abyssal-glass/d10/rare@1/asset@1', 'abyssal-glass/d10/rare@1', 1, 'builtin', 'builtin:d10', null, '{"appearance":{"accentColor":"#9dc4f0","baseColor":"#12306b","material":"glass","metalness":0.02,"roughness":0.14},"description":"Poured, not cut. A cobalt so deep it only admits to being blue at the edges, where the light gets through.","name":"Abyssal Glass D10","source":"configured","vfx":{"criticalAnimation":"void-collapse","impactEffect":"reality-crack","rollSound":"crystal_ethereal","trailEffect":"void-particles"}}'::jsonb, 'e3e6418fc410220ad847b3fbc8e5cdbc4e25b27d715bb428314f00842052a94d'),
